import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test("Upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
    // Arrange: a vendor in status "draft" owned by the member's tenant
    const member = await apiAs("member");
    const vendorResponse = await member.post("/api/vendors", {
      data: {
        name: uniqueName("DOC-01 Vendor"),
        category: "services",
        contact_email: `doc01.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@vendor.test`,
      },
    });
    expect(vendorResponse.status()).toBe(201);
    const vendor = await vendorResponse.json();
    expect(vendor.status).toBe("draft");

    // Act: upload insurance_certificate.txt as kind "insurance_certificate"
    const fileName = "insurance_certificate.txt";
    const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: fileName,
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample(fileName)),
        },
      },
    });

    // Assert: response status is 201 and the document is processing
    expect(response.status()).toBe(201);
    const document = await response.json();
    expect(document.vendor_id).toBe(vendor.id);
    expect(document.kind).toBe("insurance_certificate");
    expect(document.status).toBe("processing");

    // Assert: an audit event "document.uploaded" is recorded for the vendor
    const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditResponse.status()).toBe(200);
    const audit = await auditResponse.json();
    const uploaded = audit.items.filter(
      (event: { action: string }) => event.action === "document.uploaded",
    );
    expect(uploaded.length).toBeGreaterThanOrEqual(1);
  });
});
